import math

# Task: Calculate k = lcm(ord_16(3), ord_625(3))

# 1. Calculate k1 = ord_16(3)
# phi(16) = 8. Possible orders: 1, 2, 4, 8.
def order(base, modulus):
    if math.gcd(base, modulus) != 1:
        return None
    phi = modulus - modulus // 2 if modulus == 16 else modulus - modulus // 5 if modulus == 625 else None

    # Only checking divisors of phi for simplicity, though 3 is small.
    if modulus == 16:
        possible_orders = [d for d in [1, 2, 4, 8] if d > 0]
    elif modulus == 625:
        possible_orders = [d for d in [1, 2, 4, 5, 10, 20, 25, 50, 100, 125, 250, 500] if d > 0 and 500 % d == 0]
    else:
        return None # Should not happen

    for k in possible_orders:
        if pow(base, k, modulus) == 1:
            return k
    return None

k1 = order(3, 16)
print(f"ord_16(3) = {k1}")

# 2. Calculate k2 = ord_625(3)
k2 = order(3, 625)
print(f"ord_625(3) = {k2}")

# 3. Calculate k = lcm(k1, k2)
def lcm(a, b):
    return abs(a * b) // math.gcd(a, b)

if k1 is not None and k2 is not None:
    k_total = lcm(k1, k2)
    print(f"lcm({k1}, {k2}) = {k_total}")
else:
    print("Could not find orders.")

def power(a, b, m):
    res = 1
    a = a % m
    while b > 0:
        if b % 2 == 1:
            res = (res * a) % m
        a = (a * a) % m
        b //= 2
    return res

# Check the order modulo 10000 for exponent 500
order_check = power(3, 500, 10000)
print(f"3^500 mod 10000: {order_check}")

# Check the order modulo 16
def check_ord_16(a, m):
    k = 1
    while True:
        if power(a, k, m) == 1:
            return k
        k += 1

print(f"Order of 3 mod 16: {check_ord_16(3, 16)}")

# Check the order modulo 625
def check_ord_625(a, m):
    k = 1
    while True:
        if power(a, k, m) == 1:
            return k
        k += 1
        # Safety break, although Euler's phi(625)=500 should cap it
        if k > 1000:
             return "Exceeded safe limit"

# Note: Calculating ord_625(3) directly might be slow if the order is large, 
# but we know it must divide 500. Let's just verify 3^500 mod 625.
print(f"3^500 mod 625: {power(3, 500, 625)}")

